package com.example.onlineshop.catalog.api;
import com.example.onlineshop.catalog.application.*;import com.example.onlineshop.catalog.domain.*;import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;import org.springframework.web.servlet.resource.NoResourceFoundException;
@RestControllerAdvice class CatalogExceptionHandler {
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(CatalogExceptionHandler.class);
 @ExceptionHandler({HttpMessageNotReadableException.class,MethodArgumentTypeMismatchException.class,CatalogV2Controller.MalformedCatalogRequestException.class}) ResponseEntity<ProblemDetail> malformed(Exception e,HttpServletRequest r){return problem(400,"MALFORMED_REQUEST","Malformed request","Request could not be parsed",r,List.of());}
 @ExceptionHandler(InvalidCatalogQueryException.class) ResponseEntity<ProblemDetail> invalidQuery(InvalidCatalogQueryException e,HttpServletRequest r){return problem(422,"INVALID_CATALOG_QUERY","Invalid catalog query","Catalog query validation failed",r,e.violations());}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ProblemDetail> invalid(MethodArgumentNotValidException e,HttpServletRequest r){var violations=e.getBindingResult().getFieldErrors().stream().map(x->Map.of("field",x.getField(),"message",Objects.toString(x.getDefaultMessage(),"invalid"))).toList();return problem(422,"INVALID_PRODUCT","Validation failed","Product validation failed",r,violations);}
 @ExceptionHandler(ProductValidationException.class) ResponseEntity<ProblemDetail> invalid(ProductValidationException e,HttpServletRequest r){return problem(422,"INVALID_PRODUCT","Validation failed",e.getMessage(),r,List.of(Map.of("field","request","message",e.getMessage())));}
 @ExceptionHandler(OptimisticConflictException.class) ResponseEntity<ProblemDetail> conflict(Exception e,HttpServletRequest r){return problem(409,"CATALOG_VERSION_CONFLICT","Conflict","Catalog data was changed by another request",r,List.of());}
 @ExceptionHandler(ProductNotFoundException.class) ResponseEntity<ProblemDetail> missing(Exception e,HttpServletRequest r){return problem(404,"PRODUCT_NOT_FOUND","Product not found","Product was not found",r,List.of());}
 @ExceptionHandler(NoResourceFoundException.class) ResponseEntity<ProblemDetail> routeMissing(Exception e,HttpServletRequest r){return problem(404,"RESOURCE_NOT_FOUND","Resource not found","Resource was not found",r,List.of());}
 @ExceptionHandler(HttpRequestMethodNotSupportedException.class) ResponseEntity<ProblemDetail> method(Exception e,HttpServletRequest r){return problem(405,"METHOD_NOT_ALLOWED","Method not allowed",e.getMessage(),r,List.of());}
 @ExceptionHandler(HttpMediaTypeNotSupportedException.class) ResponseEntity<ProblemDetail> media(Exception e,HttpServletRequest r){return problem(415,"UNSUPPORTED_MEDIA_TYPE","Unsupported media type",e.getMessage(),r,List.of());}
 @ExceptionHandler(Exception.class) ResponseEntity<ProblemDetail> internal(Exception e,HttpServletRequest r)throws Exception{if(!r.getRequestURI().startsWith("/api/v2/"))throw e;LOG.error("Unhandled catalog request failure correlationId={}",r.getAttribute(CatalogCorrelationFilter.ATTRIBUTE),e);return problem(500,"INTERNAL_ERROR","Internal server error","An unexpected error occurred",r,List.of());}
 private ResponseEntity<ProblemDetail> problem(int status,String code,String title,String detail,HttpServletRequest request,List<?> violations){var p=ProblemDetail.forStatusAndDetail(HttpStatus.valueOf(status),detail);p.setTitle(title);p.setType(URI.create("https://github.com/exedeehuashan/online-shop/blob/main/docs/problem-details.md#"+code.toLowerCase().replace('_','-')));p.setInstance(URI.create(request.getRequestURI()));p.setProperty("code",code);p.setProperty("violations",violations);p.setProperty("correlationId",request.getRequestURI().startsWith("/api/v2/")?request.getAttribute(CatalogCorrelationFilter.ATTRIBUTE):request.getHeader(CatalogCorrelationFilter.HEADER));return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}
}
